import{_ as l,o as i,c as t,O as e}from"./chunks/framework.db831a78.js";const c=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/07-计算机网络.md","filePath":"interview/后端/Java/07-计算机网络.md","lastUpdated":null}'),r={name:"interview/后端/Java/07-计算机网络.md"};function h(o,a,d,u,n,s){return i(),t("div",null,a[0]||(a[0]=[e('<h1 id="计算机网络" tabindex="-1">计算机网络 <a class="header-anchor" href="#计算机网络" aria-label="Permalink to &quot;计算机网络&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="osi-七层模型与-tcp-ip-四层模型-★★☆" tabindex="-1">OSI 七层模型与 TCP/IP 四层模型 ★★☆ <a class="header-anchor" href="#osi-七层模型与-tcp-ip-四层模型-★★☆" aria-label="Permalink to &quot;OSI 七层模型与 TCP/IP 四层模型 ★★☆&quot;">​</a></h2><h3 id="osi-七层" tabindex="-1">OSI 七层 <a class="header-anchor" href="#osi-七层" aria-label="Permalink to &quot;OSI 七层&quot;">​</a></h3><ul><li>物理层、数据链路层、网络层、传输层、会话层、表示层、应用层。</li></ul><h3 id="tcp-ip-四层-更常用" tabindex="-1">TCP/IP 四层（更常用） <a class="header-anchor" href="#tcp-ip-四层-更常用" aria-label="Permalink to &quot;TCP/IP 四层（更常用）&quot;">​</a></h3><ul><li>应用层（HTTP/DNS/FTP）、传输层（TCP/UDP）、网络层（IP/ICMP）、网络接口层（数据链路 + 物理）。</li><li>记忆：应传网链。</li></ul><h3 id="各层作用" tabindex="-1">各层作用 <a class="header-anchor" href="#各层作用" aria-label="Permalink to &quot;各层作用&quot;">​</a></h3><ul><li>应用层：应用间通信（HTTP）。</li><li>传输层：端到端通信（端口，TCP/UDP）。</li><li>网络层：主机间寻址与路由（IP）。</li><li>链路层：相邻节点间传输（MAC）。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「TCP 在哪层、IP 在哪层？」→ TCP 传输层，IP 网络层。</li></ul><hr><h2 id="tcp-三次握手、四次挥手-★★★" tabindex="-1">TCP 三次握手、四次挥手 ★★★ <a class="header-anchor" href="#tcp-三次握手、四次挥手-★★★" aria-label="Permalink to &quot;TCP 三次握手、四次挥手 ★★★&quot;">​</a></h2><h3 id="三次握手-建立连接" tabindex="-1">三次握手（建立连接） <a class="header-anchor" href="#三次握手-建立连接" aria-label="Permalink to &quot;三次握手（建立连接）&quot;">​</a></h3><ol><li>客户端 → 服务端：SYN（seq=x），客户端进入 SYN_SENT。</li><li>服务端 → 客户端：SYN + ACK（seq=y，ack=x+1），服务端进入 SYN_RCVD。</li><li>客户端 → 服务端：ACK（ack=y+1），双方进入 ESTABLISHED。</li></ol><h3 id="为什么三次不是两次-四次" tabindex="-1">为什么三次不是两次/四次 <a class="header-anchor" href="#为什么三次不是两次-四次" aria-label="Permalink to &quot;为什么三次不是两次/四次&quot;">​</a></h3><ul><li>两次不够：无法确认双方收发能力都正常；且能防止「失效的连接请求」建立连接（服务端收到旧 SYN 若两次握手直接建立连接会浪费资源）。</li><li>三次刚好：第三次握手让客户端确认服务端也收到了自己发的东西；四次没必要（ACK 可与 SYN 合并）。</li></ul><h3 id="四次挥手-断开连接" tabindex="-1">四次挥手（断开连接） <a class="header-anchor" href="#四次挥手-断开连接" aria-label="Permalink to &quot;四次挥手（断开连接）&quot;">​</a></h3><ol><li>主动方 → 被动方：FIN（seq=u），主动方 FIN_WAIT_1。</li><li>被动方 → 主动方：ACK（ack=u+1），被动方 CLOSE_WAIT，主动方 FIN_WAIT_2。</li><li>被动方 → 主动方：FIN（seq=w），被动方 LAST_ACK。</li><li>主动方 → 被动方：ACK（ack=w+1），主动方 TIME_WAIT（2MSL 后关闭），被动方 CLOSED。</li></ol><h3 id="为什么四次不是三次" tabindex="-1">为什么四次不是三次 <a class="header-anchor" href="#为什么四次不是三次" aria-label="Permalink to &quot;为什么四次不是三次&quot;">​</a></h3><ul><li>收到 FIN 表示对方不再发送数据，但自己可能还有数据要发，ACK 和 FIN 需分开，所以是四次（被动方先回 ACK，发完数据再发 FIN）。</li></ul><h3 id="time-wait-为什么-2msl" tabindex="-1">TIME_WAIT 为什么 2MSL <a class="header-anchor" href="#time-wait-为什么-2msl" aria-label="Permalink to &quot;TIME_WAIT 为什么 2MSL&quot;">​</a></h3><ul><li>确保最后一个 ACK 能到达（若丢失，对方重发 FIN，能再回 ACK）；让本连接的报文在网络中消散，避免影响下一个新连接。</li><li>TIME_WAIT 过多会占用端口资源。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「SYN 洪水攻击？」→ 大量伪造 SYN 使服务端半连接队列满，无法响应正常请求；防御：SYN Cookie、限流、增大队列。</li></ul><hr><h2 id="tcp-与-udp-区别-★★★" tabindex="-1">TCP 与 UDP 区别 ★★★ <a class="header-anchor" href="#tcp-与-udp-区别-★★★" aria-label="Permalink to &quot;TCP 与 UDP 区别 ★★★&quot;">​</a></h2><table><thead><tr><th>维度</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接</td><td>面向连接</td><td>无连接</td></tr><tr><td>可靠</td><td>可靠（确认/重传）</td><td>不可靠</td></tr><tr><td>顺序</td><td>有序</td><td>无序</td></tr><tr><td>速度</td><td>慢</td><td>快</td></tr><tr><td>头部</td><td>20 字节</td><td>8 字节</td></tr><tr><td>场景</td><td>HTTP、文件、数据库</td><td>视频、语音、DNS、游戏</td></tr></tbody></table><ul><li>TCP 面向字节流，UDP 面向报文（保留消息边界）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「UDP 能可靠吗？」→ 应用层可实现（如 QUIC、应用层重传），但 UDP 本身不保证。</li></ul><hr><h2 id="http-与-https-区别-★★★" tabindex="-1">HTTP 与 HTTPS 区别 ★★★ <a class="header-anchor" href="#http-与-https-区别-★★★" aria-label="Permalink to &quot;HTTP 与 HTTPS 区别 ★★★&quot;">​</a></h2><table><thead><tr><th>维度</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td>安全</td><td>明文</td><td>加密（TLS/SSL）</td></tr><tr><td>端口</td><td>80</td><td>443</td></tr><tr><td>证书</td><td>无</td><td>需 CA 证书</td></tr><tr><td>性能</td><td>快</td><td>略慢（握手加密开销）</td></tr></tbody></table><h3 id="https-加密" tabindex="-1">HTTPS 加密 <a class="header-anchor" href="#https-加密" aria-label="Permalink to &quot;HTTPS 加密&quot;">​</a></h3><ul><li>混合加密：非对称加密（握手阶段交换对称密钥）+ 对称加密（数据传输）。</li><li>证书链验证身份，防中间人攻击。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「HTTPS 为什么用混合加密？」→ 非对称安全但慢（只用于交换密钥），对称快（用于大量数据传输）。</li><li>「中间人攻击怎么防？」→ CA 证书链验证服务器身份。</li></ul><hr><h2 id="https-握手过程-★★☆" tabindex="-1">HTTPS 握手过程 ★★☆ <a class="header-anchor" href="#https-握手过程-★★☆" aria-label="Permalink to &quot;HTTPS 握手过程 ★★☆&quot;">​</a></h2><ol><li>客户端发送 ClientHello（支持协议版本、加密套件、随机数）。</li><li>服务端回 ServerHello（选定加密套件、随机数）+ 证书 + ServerHelloDone。</li><li>客户端验证证书、生成预主密钥，用服务端公钥加密发送。</li><li>双方用随机数 + 预主密钥生成会话密钥。</li><li>通知切换加密，开始对称加密通信。</li></ol><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「TLS 1.3 优化了什么？」→ 减少握手 RTT（1-RTT）、废弃弱算法、更强安全。</li></ul><hr><h2 id="http-版本演进-1-0-1-1-2-3-★★★" tabindex="-1">HTTP 版本演进：1.0 / 1.1 / 2 / 3 ★★★ <a class="header-anchor" href="#http-版本演进-1-0-1-1-2-3-★★★" aria-label="Permalink to &quot;HTTP 版本演进：1.0 / 1.1 / 2 / 3 ★★★&quot;">​</a></h2><ul><li>HTTP/1.0：每次请求新建连接（短连接）。</li><li>HTTP/1.1：持久连接（keep-alive）、管道化（有限）、Host 头（一台服务器多站点）。</li><li>HTTP/2：二进制分帧、多路复用（一个连接并发多请求）、头部压缩（HPACK）、服务端推送；解决队头阻塞（应用层）。</li><li>HTTP/3：基于 QUIC（UDP），解决传输层队头阻塞，0-RTT 建连。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「HTTP/1.1 的队头阻塞？」→ 一个连接上请求串行，前面请求慢会阻塞后面；HTTP/2 多路复用解决应用层队头阻塞。</li><li>「HTTP/2 为什么还基于 TCP？」→ 传输层仍有队头阻塞（丢包重传阻塞后续），HTTP/3 换 QUIC/UDP 彻底解决。</li></ul><hr><h2 id="http-状态码-★★★" tabindex="-1">HTTP 状态码 ★★★ <a class="header-anchor" href="#http-状态码-★★★" aria-label="Permalink to &quot;HTTP 状态码 ★★★&quot;">​</a></h2><ul><li>1xx：信息（100 Continue）。</li><li>2xx：成功（200 OK、201 Created、204 无内容）。</li><li>3xx：重定向（301 永久、302 临时、304 未修改走缓存）。</li><li>4xx：客户端错误（400 参数、401 未认证、403 禁止、404 不存在、405 方法不允许、429 限流）。</li><li>5xx：服务端错误（500 内部错误、502 网关错误、503 不可用、504 网关超时）。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「301 和 302 区别？」→ 301 永久重定向（搜索引擎更新索引、浏览器缓存），302 临时。</li><li>「502 和 504 区别？」→ 502 网关收到无效响应（上游挂了），504 网关超时（上游响应慢）。</li></ul><hr><h2 id="get-与-post-区别-★★★" tabindex="-1">GET 与 POST 区别 ★★★ <a class="header-anchor" href="#get-与-post-区别-★★★" aria-label="Permalink to &quot;GET 与 POST 区别 ★★★&quot;">​</a></h2><ul><li>语义：GET 获取资源、POST 提交数据。</li><li>参数位置：GET 放 URL（有长度限制、明文）、POST 放请求体。</li><li>缓存：GET 可缓存、POST 一般不可缓存。</li><li>幂等：GET 幂等（可重复无副作用）、POST 不幂等。</li><li>本质：两者都是 HTTP 方法，底层没有绝对的安全/大小限制，区别主要在语义。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「POST 比 GET 安全吗？」→ 都不是安全（POST 只是参数不在 URL 可见，抓包仍可见）；安全要靠 HTTPS。</li></ul><hr><h2 id="cookie-与-session-★★★" tabindex="-1">Cookie 与 Session ★★★ <a class="header-anchor" href="#cookie-与-session-★★★" aria-label="Permalink to &quot;Cookie 与 Session ★★★&quot;">​</a></h2><ul><li>Cookie：存在客户端的小文本，随请求自动携带，用于识别用户（如 session id）。</li><li>Session：存在服务端，通过 Cookie 里的 session id 关联，存用户状态。</li><li>区别：Cookie 存客户端（可被篡改、有大小限制），Session 存服务端（更安全但占内存、分布式需共享）。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「分布式 Session 怎么解决？」→ 存 Redis（集中式 session）、JWT 无状态、粘性会话。</li></ul><hr><h2 id="从输入-url-到页面展示全过程-前端转全栈必考-★★★" tabindex="-1">从输入 URL 到页面展示全过程（前端转全栈必考）★★★ <a class="header-anchor" href="#从输入-url-到页面展示全过程-前端转全栈必考-★★★" aria-label="Permalink to &quot;从输入 URL 到页面展示全过程（前端转全栈必考）★★★&quot;">​</a></h2><ol><li>URL 解析：判断是搜索还是网址，解析协议/域名/路径。</li><li>DNS 解析：域名 → IP（浏览器缓存 → 系统缓存 → 路由器 → 递归 DNS → 根/顶级/权威）。</li><li>建立 TCP 连接（三次握手），HTTPS 再做 TLS 握手。</li><li>发送 HTTP 请求。</li><li>服务端处理请求并返回响应（可能经过网关、负载均衡）。</li><li>浏览器解析 HTML（DOM 树）、CSS（CSSOM）、执行 JS，渲染页面（回流/重绘）。</li><li>连接保持或关闭（四次挥手）。</li></ol><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「DNS 解析过程？」→ 缓存查找 + 递归查询根/顶级/权威域名服务器。</li></ul><hr><h2 id="tcp-拥塞控制、滑动窗口、流量控制-★★☆" tabindex="-1">TCP 拥塞控制、滑动窗口、流量控制 ★★☆ <a class="header-anchor" href="#tcp-拥塞控制、滑动窗口、流量控制-★★☆" aria-label="Permalink to &quot;TCP 拥塞控制、滑动窗口、流量控制 ★★☆&quot;">​</a></h2><h3 id="流量控制" tabindex="-1">流量控制 <a class="header-anchor" href="#流量控制" aria-label="Permalink to &quot;流量控制&quot;">​</a></h3><ul><li>滑动窗口：接收方通过窗口大小告知发送方还能接收多少数据，防止发送过快淹没接收方。</li></ul><h3 id="拥塞控制" tabindex="-1">拥塞控制 <a class="header-anchor" href="#拥塞控制" aria-label="Permalink to &quot;拥塞控制&quot;">​</a></h3><ul><li>慢启动：窗口指数增长。</li><li>拥塞避免：达阈值后线性增长。</li><li>快速重传：收到 3 个重复 ACK 立即重传。</li><li>快速恢复：快速重传后进入快速恢复。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「流量控制和拥塞控制区别？」→ 流量控制是端到端（接收方能力），拥塞控制是网络层面（全局拥塞）。</li></ul><hr><h2 id="dns-解析、cdn-原理-★★☆" tabindex="-1">DNS 解析、CDN 原理 ★★☆ <a class="header-anchor" href="#dns-解析、cdn-原理-★★☆" aria-label="Permalink to &quot;DNS 解析、CDN 原理 ★★☆&quot;">​</a></h2><ul><li>DNS：域名解析为 IP；递归查询 + 迭代查询。</li><li>CDN：内容分发网络，把静态资源缓存到离用户近的边缘节点，就近返回；通过 DNS 调度（CNAME）把请求导向最近节点。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CDN 怎么加速？」→ 就近节点 + 缓存 + 回源，减少网络延迟和源站压力。</li></ul><hr><h2 id="arp、icmp、websocket-★★☆" tabindex="-1">ARP、ICMP、WebSocket ★★☆ <a class="header-anchor" href="#arp、icmp、websocket-★★☆" aria-label="Permalink to &quot;ARP、ICMP、WebSocket ★★☆&quot;">​</a></h2><ul><li>ARP：通过 IP 找 MAC 地址（局域网内）。</li><li>ICMP：网络诊断（ping/traceroute 基于它）。</li><li>WebSocket：基于 HTTP 升级的全双工长连接协议，适合实时双向通信。</li></ul><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「WebSocket 和 HTTP 区别？」→ WebSocket 建立后保持连接、双向实时；HTTP 请求-响应、单向。</li></ul><hr><h2 id="对称加密与非对称加密-★★☆" tabindex="-1">对称加密与非对称加密 ★★☆ <a class="header-anchor" href="#对称加密与非对称加密-★★☆" aria-label="Permalink to &quot;对称加密与非对称加密 ★★☆&quot;">​</a></h2><ul><li>对称加密：同一密钥加解密，快（AES/DES），问题在密钥分发。</li><li>非对称加密：公钥加密私钥解密（或反之），慢（RSA/ECC），用于密钥交换和签名。</li></ul><h3 id="追问应对-13" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-13" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「数字签名是什么？」→ 用私钥对摘要加密，接收方用公钥验证，保证数据完整性 + 身份认证。</li></ul><hr><h2 id="负载均衡算法-★★☆" tabindex="-1">负载均衡算法 ★★☆ <a class="header-anchor" href="#负载均衡算法-★★☆" aria-label="Permalink to &quot;负载均衡算法 ★★☆&quot;">​</a></h2><ul><li>轮询、加权轮询、随机、最少连接、一致性哈希、源地址哈希。</li><li>一致性哈希：节点变化时最小化数据迁移，适合缓存/分片。</li></ul><h3 id="追问应对-14" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-14" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「一致性哈希怎么解决数据倾斜？」→ 虚拟节点，让节点在哈希环上分布更均匀。</li></ul>',97)]))}const T=l(r,[["render",h]]);export{c as __pageData,T as default};
